arguments.file_text:
.chat-container {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Channel Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background-color: #1a1d21;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #333;
}

.sidebar-header {
    padding: 16px 20px;
    border-bottom: 1px solid #333;
}

.sidebar-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1.1rem;
}

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 10px 20px;
    cursor: pointer;
    position: relative;
    transition: background-color 0.15s;
}

.channel-item:hover {
    background-color: #2c2f33;
}

.channel-item.active {
    background-color: #1264a3;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    margin-bottom: 2px;
}

.channel-description {
    font-size: 0.75rem;
    color: #999;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.channel-item.active .channel-description {
    color: #ddd;
}

.unread-badge {
    position: absolute;
    top: 12px;
    right: 16px;
    background-color: #e01e5a;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main Message Area */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background-color: #fff;
    min-width: 0;
}

.message-area.thread-open {
    max-width: 55%;
}

.message-header {
    padding: 16px 24px;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

.message-header h2 {
    margin: 0 0 4px 0;
    font-size: 1.2rem;
    color: #1d1c1d;
}

.message-header p {
    margin: 0;
    color: #616061;
    font-size: 0.85rem;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 24px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #888;
    font-size: 0.85rem;
}

.message-item {
    position: relative;
    padding: 8px 12px;
    margin-bottom: 4px;
    border-radius: 6px;
    transition: background-color 0.1s;
}

.message-item:hover {
    background-color: #f8f8f8;
}

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 4px;
}

.message-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #1d1c1d;
}

.message-time {
    font-size: 0.75rem;
    color: #999;
}

.message-content {
    font-size: 0.9rem;
    color: #1d1c1d;
    line-height: 1.5;
    white-space: pre-wrap;
    word-wrap: break-word;
}

/* Reactions */
.reaction-row {
    display: flex;
    gap: 6px;
    margin-top: 6px;
    flex-wrap: wrap;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    background-color: #f0f4ff;
    border: 1px solid #d4daf0;
    border-radius: 12px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background-color 0.15s;
}

.reaction-badge:hover {
    background-color: #e0e8ff;
}

/* Thread Link */
.thread-link {
    margin-top: 6px;
    font-size: 0.8rem;
    color: #1264a3;
    cursor: pointer;
    font-weight: 500;
}

